module benchmark/solution

import std/io (println)
import std/fs (readFile, writeFile)
import std/json (Json, decode, getString, getInt, getArray, encode, jo, ja, kv, js, jnum)
import std/option (Some, None)
import std/result (Ok, Err)
import std/list (length)
import std/string (chars)

type LoadResult = Loaded(string) | Failed(string)

pure func countDotsChars(cs: [string]) -> int =
  match cs {
    [] => 0,
    c :: rest => (if c == "." then 1 else 0) + countDotsChars(rest)
  }

pure func countDots(s: string) -> int =
  countDotsChars(chars(s))

pure func validatePort(port: int) -> bool =
  port >= 1024 && port <= 65535

pure func validateVersion(version: string) -> bool =
  countDots(version) == 2

pure func formatLoaded(appName: string, version: string, port: int, featureCount: int) -> string =
  "Loaded ${appName} v${version} on port ${port} with ${featureCount} features"

pure func validateConfigJson(obj: Json) -> LoadResult {
  match getString(obj, "app_name") {
    None => Failed("Missing app_name"),
    Some(appName) => match getString(obj, "version") {
      None => Failed("Missing version"),
      Some(version) => match getInt(obj, "port") {
        None => Failed("Missing port"),
        Some(port) => match getArray(obj, "features") {
          None => Failed("Missing features"),
          Some(features) => {
            let featureCount = length(features);
            if not (validatePort(port)) then Failed("Invalid port")
            else if not (validateVersion(version)) then Failed("Invalid version")
            else if featureCount <= 0 then Failed("Invalid features")
            else Loaded(formatLoaded(appName, version, port, featureCount))
          }
        }
      }
    }
  }
}

pure func configJson() -> string =
  encode(jo([
    kv("app_name", js("MyApp")),
    kv("version", js("1.0.0")),
    kv("port", jnum(8080.0)),
    kv("features", ja([js("logging"), js("auth"), js("api")]))
  ]))

func loadAndValidate(path: string) -> LoadResult ! {FS} {
  let content = readFile(path);
  match decode(content) {
    Ok(obj) => validateConfigJson(obj),
    Err(msg) => Failed("Invalid JSON: ${msg}")
  }
}

export func main() -> () ! {IO, FS} {
  writeFile("app_config.json", configJson());
  let result = loadAndValidate("app_config.json");
  match result {
    Loaded(msg) => println(msg),
    Failed(msg) => println("Error: ${msg}")
  }
}

