package main

import (
	"encoding/json"
	"fmt"
	"os"
	"strings"
)

type Config struct {
	AppName  string   `json:"app_name"`
	Version  string   `json:"version"`
	Port     int      `json:"port"`
	Features []string `json:"features"`
}

func main() {
	// Create the config file
	config := Config{
		AppName:  "MyApp",
		Version:  "1.0.0",
		Port:     8080,
		Features: []string{"logging", "auth", "api"},
	}

	// Write config to JSON file
	data, err := json.Marshal(config)
	if err != nil {
		fmt.Println("Error marshaling config:", err)
		return
	}

	err = os.WriteFile("app_config.json", data, 0644)
	if err != nil {
		fmt.Println("Error writing config file:", err)
		return
	}

	// Load and validate config
	loadedConfig, err := loadAndValidateConfig("app_config.json")
	if err != nil {
		fmt.Println("Error loading config:", err)
		return
	}

	// Print result
	fmt.Printf("Loaded %s v%s on port %d with %d features\n",
		loadedConfig.AppName,
		loadedConfig.Version,
		loadedConfig.Port,
		len(loadedConfig.Features),
	)
}

func loadAndValidateConfig(filename string) (*Config, error) {
	// Read the JSON file
	data, err := os.ReadFile(filename)
	if err != nil {
		return nil, err
	}

	// Parse the JSON content
	var config Config
	err = json.Unmarshal(data, &config)
	if err != nil {
		return nil, err
	}

	// Validate port is between 1024 and 65535
	if config.Port < 1024 || config.Port > 65535 {
		return nil, fmt.Errorf("port must be between 1024 and 65535, got %d", config.Port)
	}

	// Validate version contains exactly two dots (X.Y.Z format)
	dotCount := strings.Count(config.Version, ".")
	if dotCount != 2 {
		return nil, fmt.Errorf("version must have exactly two dots (X.Y.Z format), got %s", config.Version)
	}

	// Validate features list is not empty
	if len(config.Features) == 0 {
		return nil, fmt.Errorf("features list cannot be empty")
	}

	return &config, nil
}

