const fs = require('fs');
const path = require('path');

const configData = {
  app_name: "MyApp",
  version: "1.0.0",
  port: 8080,
  features: ["logging", "auth", "api"]
};

const configPath = path.join(__dirname, 'app_config.json');

// Create the config file
fs.writeFileSync(configPath, JSON.stringify(configData, null, 2));

// Load and validate
function loadAndValidateConfig(filePath) {
  const content = fs.readFileSync(filePath, 'utf-8');
  const config = JSON.parse(content);

  // Validate port is between 1024 and 65535
  if (config.port < 1024 || config.port > 65535) {
    throw new Error(`Port ${config.port} is not between 1024 and 65535`);
  }

  // Validate version contains exactly two dots (X.Y.Z format)
  const dotCount = (config.version.match(/\./g) || []).length;
  if (dotCount !== 2) {
    throw new Error(`Version ${config.version} does not have exactly two dots`);
  }

  // Validate features list is not empty
  if (!Array.isArray(config.features) || config.features.length === 0) {
    throw new Error('Features list is empty');
  }

  return config;
}

const config = loadAndValidateConfig(configPath);
console.log(`Loaded ${config.app_name} v${config.version} on port ${config.port} with ${config.features.length} features`);

