module benchmark/solution

export type Tree = Leaf | Node(Tree, int, Tree)

export func insert(t: Tree, x: int) -> Tree =
  match t {
    Leaf => Node(Leaf, x, Leaf),
    Node(left, value, right) =>
      if x < value then Node(insert(left, x), value, right)
      else if x > value then Node(left, value, insert(right, x))
      else t
  }

export func contains(t: Tree, x: int) -> bool =
  match t {
    Leaf => false,
    Node(left, value, right) =>
      if x == value then true
      else if x < value then contains(left, x)
      else contains(right, x)
  }

export func size(t: Tree) -> int =
  match t {
    Leaf => 0,
    Node(left, _, right) => 1 + size(left) + size(right)
  }

export func isBST(t: Tree, low: int, high: int) -> bool =
  match t {
    Leaf => true,
    Node(left, value, right) =>
      value > low && value < high && isBST(left, low, value) && isBST(right, value, high)
  }

export func insertPreservesBST(x: int) -> bool =
  if x > -999999 && x < 999999 then isBST(insert(Leaf, x), -999999, 999999) else true

export func insertThenFind(x: int) -> bool =
  contains(insert(Leaf, x), x)

export func main() -> () ! {IO} {
  let tree = insert(insert(insert(Leaf, 5), 3), 7);
  println(show(size(tree)));
  println(show(contains(tree, 3)));
  println(show(contains(tree, 4)));
  println(show(isBST(tree, -999999, 999999)));
  println(show(insertPreservesBST(42)));
  println(show(insertThenFind(42)))
}

