from typing import Union

# BST node types
class Leaf:
    pass

class Node:
    def __init__(self, value: int, left: Union['Node', 'Leaf'], right: Union['Node', 'Leaf']):
        self.value = value
        self.left = left
        self.right = right

# Type alias for BST
BST = Union[Node, Leaf]

# Create a singleton Leaf instance
Leaf = Leaf()

def insert(tree: BST, value: int) -> BST:
    """Insert a value into the BST. No duplicates allowed."""
    if type(tree).__name__ == 'Leaf':
        return Node(value, Leaf, Leaf)

    if value < tree.value:
        return Node(tree.value, insert(tree.left, value), tree.right)
    elif value > tree.value:
        return Node(tree.value, tree.left, insert(tree.right, value))
    else:
        # Duplicate - return tree unchanged
        return tree

def contains(tree: BST, value: int) -> bool:
    """Search for a value in the BST."""
    if type(tree).__name__ == 'Leaf':
        return False

    if value == tree.value:
        return True
    elif value < tree.value:
        return contains(tree.left, value)
    else:
        return contains(tree.right, value)

def size(tree: BST) -> int:
    """Return the number of nodes in the BST."""
    if type(tree).__name__ == 'Leaf':
        return 0
    return 1 + size(tree.left) + size(tree.right)

def isBST(tree: BST, min_bound: int, max_bound: int) -> bool:
    """Validate that the tree is a valid BST within the given bounds."""
    if type(tree).__name__ == 'Leaf':
        return True

    # Check if current node is within bounds
    if tree.value <= min_bound or tree.value >= max_bound:
        return False

    # Recursively check left and right subtrees
    return isBST(tree.left, min_bound, tree.value) and isBST(tree.right, tree.value, max_bound)

def insertPreservesBST(value: int) -> bool:
    """Proof: inserting a value into a valid BST preserves BST property."""
    # Build a BST
    tree = insert(insert(insert(Leaf, 5), 3), 7)

    # Check it's a valid BST before insertion
    before = isBST(tree, -999999, 999999)

    # Insert the new value
    new_tree = insert(tree, value)

    # Check it's still a valid BST after insertion
    after = isBST(new_tree, -999999, 999999)

    return before and after

def insertThenFind(value: int) -> bool:
    """Proof: a value inserted into a BST can be found."""
    # Build a BST
    tree = insert(insert(insert(Leaf, 5), 3), 7)

    # Insert the value
    new_tree = insert(tree, value)

    # We should be able to find it (unless it was a duplicate)
    # The proof is that if we insert value, it's either:
    # 1. Already in the tree (duplicate) - tree unchanged, value is still findable
    # 2. Not in the tree - value is inserted and findable

    return contains(new_tree, value) or contains(tree, value)

def main():
    # Test cases
    tree = insert(insert(insert(Leaf, 5), 3), 7)

    print(size(tree))
    print("true" if contains(tree, 3) else "false")
    print("true" if contains(tree, 4) else "false")
    print("true" if isBST(tree, -999999, 999999) else "false")
    print("true" if insertPreservesBST(42) else "false")
    print("true" if insertThenFind(42) else "false")

if __name__ == "__main__":
    main()

