from __future__ import annotations


def determinant(matrix: tuple[tuple[int, ...], ...]) -> int:
    size = len(matrix)
    if size == 1:
        return matrix[0][0]
    if size == 2:
        a, b = matrix[0]
        c, d = matrix[1]
        return a * d - b * c

    total = 0
    for col, value in enumerate(matrix[0]):
        minor = tuple(
            tuple(row[j] for j in range(size) if j != col)
            for row in matrix[1:]
        )
        sign = -1 if col % 2 else 1
        total += sign * value * determinant(minor)
    return total


def det2(a: int, b: int, c: int, d: int) -> int:
    return determinant(((a, b), (c, d)))


def det3(
    a: int,
    b: int,
    c: int,
    d: int,
    e: int,
    f: int,
    g: int,
    h: int,
    i: int,
) -> int:
    return determinant(((a, b, c), (d, e, f), (g, h, i)))


def identityDet() -> bool:
    return determinant(((1, 0, 0), (0, 1, 0), (0, 0, 1))) == 1


def zeroRowDet(a: int, b: int, c: int, d: int, e: int, f: int) -> bool:
    return determinant(((a, b, c), (0, 0, 0), (d, e, f))) == 0


def main() -> None:
    print(det2(3, 8, 4, 6))
    print(det3(6, 1, 1, 4, -2, 5, 2, 8, 7))
    print(det3(1, 0, 0, 0, 1, 0, 0, 0, 1))
    print(str(identityDet()).lower())
    print(str(zeroRowDet(3, 5, 7, 2, 4, 6)).lower())


if __name__ == "__main__":
    main()

def encode(s: str) -> str:
    """Run-length encode a string."""
    if not s:
        return ""

    result = []
    count = 1
    prev = s[0]

    for c in s[1:]:
        if c == prev:
            count += 1
        else:
            result.append(f"{count}{prev}")
            prev = c
            count = 1
    result.append(f"{count}{prev}")

    return "".join(result)

def decode(s: str) -> str:
    """Decode a run-length encoded string."""
    if not s:
        return ""

    result = []
    i = 0
    while i < len(s):
        j = i
        while j < len(s) and s[j].isdigit():
            j += 1
        count = int(s[i:j])
        char = s[j]
        result.append(char * count)
        i = j + 1

    return "".join(result)

def roundtrip(s: str) -> bool:
    """Prove that encoding and decoding are invariant."""
    return s == decode(encode(s))

def singleCharEncode(s: str) -> bool:
    """Test encoding a single character."""
    return s == decode(encode(s))

if __name__ == "__main__":
    print(encode("aaabbc"))
    print(encode("xyz"))
    print(decode("3a2b1c"))
    print(decode("1x1y1z"))
    print(roundtrip("hello"))
    print(singleCharEncode("q"))

