module benchmark/solution
import std/string (startsWith, substring, length)

export func toRoman(n: int) -> string =
  if n >= 1000 then "M${toRoman(n - 1000)}"
  else if n >= 900 then "CM${toRoman(n - 900)}"
  else if n >= 500 then "D${toRoman(n - 500)}"
  else if n >= 400 then "CD${toRoman(n - 400)}"
  else if n >= 100 then "C${toRoman(n - 100)}"
  else if n >= 90 then "XC${toRoman(n - 90)}"
  else if n >= 50 then "L${toRoman(n - 50)}"
  else if n >= 40 then "XL${toRoman(n - 40)}"
  else if n >= 10 then "X${toRoman(n - 10)}"
  else if n >= 9 then "IX${toRoman(n - 9)}"
  else if n >= 5 then "V${toRoman(n - 5)}"
  else if n >= 4 then "IV${toRoman(n - 4)}"
  else if n >= 1 then "I${toRoman(n - 1)}"
  else ""

func rest(s: string, n: int) -> string =
  substring(s, n, length(s))

export func fromRoman(s: string) -> int =
  if s == "" then 0
  else if startsWith(s, "CM") then 900 + fromRoman(rest(s, 2))
  else if startsWith(s, "CD") then 400 + fromRoman(rest(s, 2))
  else if startsWith(s, "XC") then 90 + fromRoman(rest(s, 2))
  else if startsWith(s, "XL") then 40 + fromRoman(rest(s, 2))
  else if startsWith(s, "IX") then 9 + fromRoman(rest(s, 2))
  else if startsWith(s, "IV") then 4 + fromRoman(rest(s, 2))
  else if startsWith(s, "M") then 1000 + fromRoman(rest(s, 1))
  else if startsWith(s, "D") then 500 + fromRoman(rest(s, 1))
  else if startsWith(s, "C") then 100 + fromRoman(rest(s, 1))
  else if startsWith(s, "L") then 50 + fromRoman(rest(s, 1))
  else if startsWith(s, "X") then 10 + fromRoman(rest(s, 1))
  else if startsWith(s, "V") then 5 + fromRoman(rest(s, 1))
  else if startsWith(s, "I") then 1 + fromRoman(rest(s, 1))
  else 0

export func roundtrip(n: int) -> bool =
  fromRoman(toRoman(n)) == n

export func distinctEncoding(a: int, b: int) -> bool =
  if a != b then toRoman(a) != toRoman(b) else true

export func main() -> () ! {IO} {
  println(toRoman(1994));
  println(toRoman(58));
  println(toRoman(3999));
  println(show(fromRoman("MCMXCIV")));
  println(show(fromRoman("LVIII")));
  println(show(roundtrip(2024)));
  println(show(distinctEncoding(4, 6)))
}

module benchmark/solution

export type SSet = SNil | SCons(int, SSet) deriving (Eq)

export func sLength(s: SSet) -> int =
  match s {
    SNil => 0,
    SCons(_, rest) => 1 + sLength(rest)
  }

export func isSorted(s: SSet) -> bool =
  match s {
    SNil => true,
    SCons(_, SNil) => true,
    SCons(x, SCons(y, rest)) => x < y && isSorted(SCons(y, rest))
  }

export func sMerge(a: SSet, b: SSet) -> SSet =
  match a {
    SNil => b,
    SCons(x, xs) => match b {
      SNil => a,
      SCons(y, ys) =>
        if x < y then SCons(x, sMerge(xs, b))
        else if x > y then SCons(y, sMerge(a, ys))
        else SCons(x, sMerge(xs, ys))
    }
  }

export func sIntersect(a: SSet, b: SSet) -> SSet =
  match a {
    SNil => SNil,
    SCons(x, xs) => match b {
      SNil => SNil,
      SCons(y, ys) =>
        if x < y then sIntersect(xs, b)
        else if x > y then sIntersect(a, ys)
        else SCons(x, sIntersect(xs, ys))
    }
  }

func toStrItems(s: SSet) -> string =
  match s {
    SNil => "",
    SCons(x, SNil) => show(x),
    SCons(x, rest) => "${show(x)}, ${toStrItems(rest)}"
  }

export func toStr(s: SSet) -> string =
  "[${toStrItems(s)}]"

export func mergePreservesSorted(a: SSet, b: SSet) -> bool =
  if isSorted(a) && isSorted(b) then isSorted(sMerge(a, b)) else true

export func intersectPreservesSorted(a: SSet, b: SSet) -> bool =
  if isSorted(a) && isSorted(b) then isSorted(sIntersect(a, b)) else true

export func inclusionExclusion(a: SSet, b: SSet) -> bool =
  if isSorted(a) && isSorted(b) then
    sLength(sMerge(a, b)) + sLength(sIntersect(a, b)) == sLength(a) + sLength(b)
  else true

export func main() -> () ! {IO} {
  let a = SCons(1, SCons(3, SCons(5, SNil)));
  let b = SCons(2, SCons(3, SCons(4, SNil)));
  let merged = sMerge(a, b);
  let intersected = sIntersect(a, b);
  println(toStr(merged));
  println(toStr(intersected));
