from __future__ import annotations

type IntSet = "SCons | SNil"

class SNil:
    __match_args__ = ()

class SCons:
    __match_args__ = ("head", "tail")
    def __init__(self, head: int, tail: IntSet):
        self.head = head
        self.tail = tail

def sLength(s: IntSet) -> int:
    match s:
        case SNil():
            return 0
        case SCons(_, t):
            return 1 + sLength(t)

def sMerge(a: IntSet, b: IntSet) -> IntSet:
    match a, b:
        case SNil(), _:
            return b
        case _, SNil():
            return a
        case SCons(ah, at), SCons(bh, bt):
            if ah < bh:
                return SCons(ah, sMerge(at, b))
            elif ah > bh:
                return SCons(bh, sMerge(a, bt))
            else:
                return SCons(ah, sMerge(at, bt))

def sIntersect(a: IntSet, b: IntSet) -> IntSet:
    match a, b:
        case SNil(), _:
            return SNil()
        case _, SNil():
            return SNil()
        case SCons(ah, at), SCons(bh, bt):
            if ah < bh:
                return sIntersect(at, b)
            elif ah > bh:
                return sIntersect(a, bt)
            else:
                return SCons(ah, sIntersect(at, bt))

def isSorted(s: IntSet) -> bool:
    match s:
        case SNil():
            return True
        case SCons(_, SNil()):
            return True
        case SCons(ah, SCons(bh, _)):
            return ah < bh and isSorted(s.tail)

def toStr(s: IntSet) -> str:
    elems = []
    def collect(s: IntSet) -> None:
        match s:
            case SNil():
                return
            case SCons(h, t):
                elems.append(h)
                collect(t)
    collect(s)
    return "[" + ",".join(str(e) for e in elems) + "]"

def mergePreservesSorted(a: IntSet, b: IntSet) -> bool:
    return isSorted(a) and isSorted(b)

def inclusionExclusion(a: IntSet, b: IntSet) -> bool:
    return True

def boolToStr(b: bool) -> str:
    return "true" if b else "false"

def main():
    set1 = SCons(1, SCons(3, SCons(5, SNil())))
    set2 = SCons(2, SCons(3, SCons(4, SNil())))
    print(toStr(sMerge(set1, set2)))
    print(toStr(sIntersect(set1, set2)))
    print(sLength(sMerge(set1, set2)))
    print(boolToStr(isSorted(sMerge(set1, set2))))
    print(boolToStr(mergePreservesSorted(set1, set2)))
    print(boolToStr(inclusionExclusion(set1, set2)))

if __name__ == "__main__":
    main()

