type User = {name: string, age: int, email: string}

pure func dropHeader(lines: [string]) -> [string] =
  match lines {
    [] => [],
    _ :: rest => rest
  }

pure func parseRow(line: string) -> Option[User] {
  let cleaned = trim(line);
  if cleaned == "" then None
  else match split(cleaned, ",") {
    namePart :: agePart :: emailPart :: [] => {
      let name = trim(namePart);
      let ageText = trim(agePart);
      let email = trim(emailPart);
      match stringToInt(ageText) {
        Some(age) => if age > 0 && contains(email, "@") then Some({name: name, age: age, email: email}) else None,
        None => None
      }
    },
    _ => None
  }
}

pure func parseRows(rows: [string]) -> [User] =
  match rows {
    [] => [],
    row :: rest => match parseRow(row) {
      Some(user) => user :: parseRows(rest),
      None => parseRows(rest)
    }
  }

pure func userToJson(user: User) -> Json =
  jo([
    kv("name", js(user.name)),
    kv("age", jnum(intToFloat(user.age))),
