package main

import (
	"encoding/csv"
	"encoding/json"
	"fmt"
	"os"
	"strconv"
	"strings"
)

type User struct {
	Name  string `json:"name"`
	Age   int    `json:"age"`
	Email string `json:"email"`
}

func main() {
	// Create the CSV file with the required data
	csvContent := `name,age,email
Alice,30,alice@example.com
Bob,25,bob@example.com
Carol,35,carol@example.com`

	err := os.WriteFile("users.csv", []byte(csvContent), 0644)
	if err != nil {
		fmt.Println("Error creating CSV file:", err)
		return
	}

	// Read and parse the CSV file
	file, err := os.Open("users.csv")
	if err != nil {
		fmt.Println("Error opening CSV file:", err)
		return
	}
	defer file.Close()

	reader := csv.NewReader(file)
	records, err := reader.ReadAll()
	if err != nil {
		fmt.Println("Error reading CSV:", err)
		return
	}

	// Parse and validate records
	var users []User
	for i, record := range records {
		if i == 0 {
			// Skip header row
			continue
		}

		if len(record) < 3 {
			// Skip incomplete rows
			continue
		}

		name := strings.TrimSpace(record[0])
		ageStr := strings.TrimSpace(record[1])
		email := strings.TrimSpace(record[2])

		// Validate age: must be a positive integer
		age, err := strconv.Atoi(ageStr)
		if err != nil || age <= 0 {
			// Skip invalid rows
			continue
		}

		// Validate email: must contain "@" symbol
		if !strings.Contains(email, "@") {
			// Skip invalid rows
			continue
		}

		users = append(users, User{
			Name:  name,
			Age:   age,
			Email: email,
		})
	}

	// Convert to JSON with proper formatting
	jsonData, err := json.MarshalIndent(users, "", "  ")
	if err != nil {
		fmt.Println("Error marshaling JSON:", err)
		return
	}

	// Write JSON to file
	err = os.WriteFile("users.json", jsonData, 0644)
	if err != nil {
		fmt.Println("Error writing JSON file:", err)
		return
	}

	// Print the result message
	fmt.Printf("Converted %d valid rows to users.json\n", len(users))
}

