module benchmark/solution

pure func contains(x: int, xs: [int]) -> bool =
  match xs {
    [] => false,
    y :: rest => if x == y then true else contains(x, rest)
  }

pure func enqueue(x: int, queue: [int]) -> [int] =
  match queue {
    [] => [x],
    y :: rest => y :: enqueue(x, rest)
  }

pure func enqueueAll(xs: [int], queue: [int]) -> [int] =
  match xs {
    [] => queue,
    x :: rest => enqueueAll(rest, enqueue(x, queue))
  }

pure func neighbors(node: int, graph: [(int, [int])]) -> [int] =
  match graph {
    [] => [],
    entry :: rest => match entry {
      (n, ns) => if n == node then ns else neighbors(node, rest)
    }
  }

pure func bfsLoop(graph: [(int, [int])], queue: [int], visited: [int]) -> [int] {
  match queue {
    [] => visited,
    node :: rest =>
      if contains(node, visited) then bfsLoop(graph, rest, visited)
      else {
        let ns = neighbors(node, graph);
        let newQueue = enqueueAll(ns, rest);
        let newVisited = enqueue(node, visited);
        bfsLoop(graph, newQueue, newVisited)
      }
  }
}

pure func bfs(graph: [(int, [int])], start: int) -> [int] =
  bfsLoop(graph, [start], [])

