package main

import (
	"fmt"
)

func main() {
	// Define the graph as adjacency list
	// 1 -> [2, 3]
	// 2 -> [4]
	// 3 -> [4, 5]
	// 4 -> []
	// 5 -> []
	graph := map[int][]int{
		1: {2, 3},
		2: {4},
		3: {4, 5},
		4: {},
		5: {},
	}

	// Run BFS starting from node 1
	visited := bfs(graph, 1)

	// Print visited nodes in BFS order
	for _, node := range visited {
		fmt.Println(node)
	}
}

func bfs(graph map[int][]int, start int) []int {
	var visited []int
	var queue []int

	// Initialize: add start node to queue and mark as visited
	queue = enqueue(queue, start)
	visited = append(visited, start)

	for len(queue) > 0 {
		// Dequeue front of queue
		node := queue[0]
		queue = queue[1:]

		// Visit all neighbors
		for _, neighbor := range graph[node] {
			if !contains(neighbor, visited) {
				visited = append(visited, neighbor)
				queue = enqueue(queue, neighbor)
			}
		}
	}

	return visited
}

func contains(x int, list []int) bool {
	for _, v := range list {
		if v == x {
			return true
		}
	}
	return false
}

func enqueue(queue []int, x int) []int {
	return append(queue, x)
}

