  const queue = [start];
  const visited = [];
  const result = [];

  while (queue.length > 0) {
    const node = queue.shift();

    if (!contains(node, visited)) {
      visited.push(node);
      result.push(node);

      // Find neighbors for this node
      for (const [n, neighbors] of graph) {
        if (n === node) {
          for (const neighbor of neighbors) {
            if (!contains(neighbor, visited)) {
              enqueue(neighbor, queue);
            }
          }
          break;
        }
      }
    }
  }

  return result;
};

