import "fmt"

// Type for a function that takes an int and returns an int
type IntFunc func(int) int

// pipe returns a function that applies f first, then g
func pipe(f, g IntFunc) IntFunc {
	return func(x int) int {
		return g(f(x))
	}
}

// subtract returns x - y
func subtract(x, y int) int {
	return x - y
}

// negate returns -x
func negate(x int) int {
	return -x
}

// multiply returns x * y
func multiply(x, y int) int {
	return x * y
}

func main() {
	// Create sub4: subtract 4 from input (partial application)
	sub4 := func(x int) int {
		return subtract(x, 4)
	}

	// Create double: multiply by 2 (partial application)
	double := func(x int) int {
		return multiply(2, x)
	}

	// Create the piped function: subtract 4 first, then double
	sub4_then_double := pipe(sub4, double)

	// Apply the piped function to 11
	result := sub4_then_double(11)

	// Print the result
	fmt.Printf("Result: %d\n", result)
}

