type Stats = {info: int, errors: int, warnings: int, users: [string], total: int}

pure func logContent() -> string =
  "2024-10-29 10:00:00 INFO User logged in: alice\n2024-10-29 10:01:15 ERROR Database connection failed\n2024-10-29 10:02:30 INFO User logged in: bob\n2024-10-29 10:03:45 WARNING High memory usage: 85%\n2024-10-29 10:05:00 ERROR API timeout: /users endpoint\n2024-10-29 10:06:15 INFO User logged out: alice"

pure func initialStats() -> Stats =
  {info: 0, errors: 0, warnings: 0, users: [], total: 0}

pure func levelOfLine(line: string) -> string =
  match split(line, " ") {
    datePart :: timePart :: level :: rest => level,
    _ => ""
  }

pure func memberString(x: string, xs: [string]) -> bool =
  match xs {
    [] => false,
    y :: rest => if x == y then true else memberString(x, rest)
  }

pure func addUnique(user: string, users: [string]) -> [string] =
  if memberString(user, users) then users else user :: users

pure func userFromLine(line: string) -> [string] =
  if contains(line, "User logged") then
    match split(line, ": ") {
      prefix :: name :: rest => [trim(name)],
      _ => []
    }
  else []

pure func addLevel(stats: Stats, level: string) -> Stats =
  if level == "INFO" then
    {stats | info: stats.info + 1, total: stats.total + 1}
  else if level == "ERROR" then
    {stats | errors: stats.errors + 1, total: stats.total + 1}
  else if level == "WARNING" then
    {stats | warnings: stats.warnings + 1, total: stats.total + 1}
  else
    {stats | total: stats.total + 1}

pure func updateStats(stats: Stats, line: string) -> Stats {
  let level = levelOfLine(line);
  let withLevel = addLevel(stats, level);
  match userFromLine(line) {
    user :: rest => {withLevel | users: addUnique(user, withLevel.users)},
    [] => withLevel
  }
}

pure func analyzeLines(lines: [string], stats: Stats) -> Stats =
  match lines {
    [] => stats,
    line :: rest => analyzeLines(rest, updateStats(stats, line))
  }

pure func percent(count: int, total: int) -> int =
  if total == 0 then 0 else (count * 100) / total

pure func cmpString(a: string, b: string) -> int =
  compare(a, b)

export func main() -> () ! {IO, FS} {
  writeFile("app.log", logContent());
  let content = readFile("app.log");
  let lines = split(content, "\n");
  let stats = analyzeLines(lines, initialStats());
  let sortedUsers = sortBy(cmpString, stats.users);
  let usersText = join(", ", sortedUsers);
  println("Total log entries: ${show(stats.total)}");
  println("INFO: ${show(stats.info)} (${show(percent(stats.info, stats.total))}%)");
  println("ERROR: ${show(stats.errors)} (${show(percent(stats.errors, stats.total))}%)");
  println("WARNING: ${show(stats.warnings)} (${show(percent(stats.warnings, stats.total))}%)");
  println("Unique users: ${usersText}")
}

