// split divides a slice into two halves
func split(xs []int) ([]int, []int) {
	mid := len(xs) / 2
	return xs[:mid], xs[mid:]
}

// merge combines two sorted slices into one sorted slice
func merge(xs, ys []int) []int {
	result := make([]int, 0, len(xs)+len(ys))
	i, j := 0, 0

	for i < len(xs) && j < len(ys) {
		if xs[i] <= ys[j] {
			result = append(result, xs[i])
			i++
		} else {
			result = append(result, ys[j])
			j++
		}
	}

	// Append remaining elements
	result = append(result, xs[i:]...)
	result = append(result, ys[j:]...)

	return result
}

// mergeSort recursively sorts a slice using merge sort
func mergeSort(xs []int) []int {
	if len(xs) <= 1 {
		return xs
	}

	left, right := split(xs)
	left = mergeSort(left)
	right = mergeSort(right)

	return merge(left, right)
}

