package main

import "fmt"

type Tree interface{}

type Leaf struct {
	value int
}

type Node struct {
	left  Tree
	value int
	right Tree
}

func tree_sum(tree Tree) int {
	switch t := tree.(type) {
	case Leaf:
		return t.value
	case Node:
		return tree_sum(t.left) + t.value + tree_sum(t.right)
	default:
		return 0
	}
}

func find_max(tree Tree) int {
	switch t := tree.(type) {
	case Leaf:
		return t.value
	case Node:
		left_max := find_max(t.left)
		right_max := find_max(t.right)
		max := left_max
		if t.value > max {
			max = t.value
		}
		if right_max > max {
			max = right_max
		}
		return max
	default:
		return 0
