// Define algebraic data types
class Leaf {
  constructor(value) {
    this.value = value;
  }
}

class Node {
  constructor(left, value, right) {
    this.left = left;
    this.value = value;
    this.right = right;
  }
}

// Pattern matching with nested constructors for tree_sum
function tree_sum(tree) {
  // Match Leaf(v): return v
  if (tree instanceof Leaf) {
    return tree.value;
  }
  // Match Node(l, v, r): return tree_sum(l) + v + tree_sum(r)
  if (tree instanceof Node) {
    return tree_sum(tree.left) + tree.value + tree_sum(tree.right);
  }
  // Exhaustiveness check
  throw new Error('Non-exhaustive pattern match in tree_sum');
}

// Pattern matching with nested patterns and guards for find_max
function find_max(tree) {
  // Match Leaf(v): return v
  if (tree instanceof Leaf) {
    return tree.value;
  }
  // Match Node(l, v, r) with guards to find maximum
  if (tree instanceof Node) {
    const left_max = find_max(tree.left);
    const right_max = find_max(tree.right);
    // Guard: compare all three values (left subtree max, current node value, right subtree max)
    return Math.max(left_max, tree.value, right_max);
  }
  // Exhaustiveness check
  throw new Error('Non-exhaustive pattern match in find_max');
}

// Create sample tree: Node(Leaf(1), 5, Node(Leaf(3), 7, Leaf(2)))
const sample_tree = new Node(
  new Leaf(1),
  5,
  new Node(
    new Leaf(3),
    7,
    new Leaf(2)
  )
);

// Calculate results and print
const sum = tree_sum(sample_tree);
const max = find_max(sample_tree);

console.log(`Sum: ${sum}`);
console.log(`Max: ${max}`);

