type State = Idle | HasCredit(int) | Dispensing(int)
type Event = Insert(int) | Select(int) | DispenseDone
type Result[a, b] = Ok(a) | Err(b)

pure func vend(credit: int, price: int) -> Result[State, string] ! {} =
  if credit < price then Err("insufficient_funds") else Ok(Dispensing(credit - price))

pure func selectItem(credit: int, code: int) -> Result[State, string] ! {} =
  match code {
    1 => vend(credit, 125),
    2 => vend(credit, 75),
    3 => vend(credit, 100),
    _ => Err("unknown_item")
  }

export pure func step(state: State, event: Event) -> Result[State, string] ! {} =
  match (state, event) {
    (Idle, Insert(n)) => Ok(HasCredit(n)),
    (Idle, Select(_)) => Err("no_credit"),
    (Idle, DispenseDone) => Err("not_dispensing"),
    (HasCredit(c), Insert(n)) => Ok(HasCredit(c + n)),
    (HasCredit(c), Select(code)) => selectItem(c, code),
    (HasCredit(_), DispenseDone) => Err("not_dispensing"),
    (Dispensing(_), Insert(_)) => Err("busy"),
    (Dispensing(_), Select(_)) => Err("busy"),
    (Dispensing(_), DispenseDone) => Ok(Idle)
  }

pure func showState(state: State) -> string ! {} =
  match state {
    Idle => "IDLE",
    HasCredit(n) => "CREDIT(${n})",
    Dispensing(ch) => "DISPENSING(${ch})"
  }

pure func showResult(result: Result[State, string]) -> string ! {} =
  match result {
    Ok(state) => "ok: ${showState(state)}",
    Err(reason) => "err: ${reason}"
  }

