package main

import "fmt"

// State interface - tagged union
type State interface {
	isState()
}

// State variants
type Idle struct{}

func (Idle) isState() {}

type HasCredit struct {
	cents int
}

func (HasCredit) isState() {}

type Dispensing struct {
	change int
}

func (Dispensing) isState() {}

// Event interface - tagged union
type Event interface {
	isEvent()
}

// Event variants
type Insert struct {
	cents int
}

func (Insert) isEvent() {}

type Select struct {
	code int
}

func (Select) isEvent() {}

type DispenseDone struct{}

func (DispenseDone) isEvent() {}

// Result type - Ok or Err
type Result struct {
	isOk  bool
	state State
	err   string
}

func Ok(s State) Result {
	return Result{isOk: true, state: s}
}

func Err(msg string) Result {
	return Result{isOk: false, err: msg}
}

// Price function
func price(code int) int {
	switch code {
	case 1:
		return 125 // cola
	case 2:
		return 75 // chips
	case 3:
		return 100 // water
	default:
		return -1
	}
}

// Step function - state machine transition with pattern matching
func step(state State, event Event) Result {
	switch s := state.(type) {
	case Idle:
		switch e := event.(type) {
		case Insert:
			return Ok(HasCredit{cents: e.cents})
		case Select:
			return Err("no_credit")
		case DispenseDone:
			return Err("not_dispensing")
		}

	case HasCredit:
		switch e := event.(type) {
		case Insert:
			return Ok(HasCredit{cents: s.cents + e.cents})
		case Select:
			if e.code < 1 || e.code > 3 {
				return Err("unknown_item")
			}
			p := price(e.code)
			if s.cents < p {
				return Err("insufficient_funds")
			}
			return Ok(Dispensing{change: s.cents - p})
		case DispenseDone:
			return Err("not_dispensing")
		}

	case Dispensing:
		switch event.(type) {
		case Insert:
			return Err("busy")
		case Select:
			return Err("busy")
		case DispenseDone:
			return Ok(Idle{})
		}
	}

	return Err("unknown_state")
}

// Format state for output
func formatState(state State) string {
	switch s := state.(type) {
	case Idle:
		return "IDLE"
	case HasCredit:
		return fmt.Sprintf("CREDIT(%d)", s.cents)
	case Dispensing:
		return fmt.Sprintf("DISPENSING(%d)", s.change)
	}
	return "UNKNOWN"
}

func main() {
	var currentState State = Idle{}

	events := []Event{
		Insert{cents: 50},
		Select{code: 1},
		Insert{cents: 100},
		Select{code: 1},
		Insert{cents: 50},
		DispenseDone{},
		Select{code: 2},
		Insert{cents: 100},
		Select{code: 2},
		DispenseDone{},
	}

	for _, event := range events {
		result := step(currentState, event)
		if result.isOk {
			fmt.Printf("ok: %s\n", formatState(result.state))
			currentState = result.state
		} else {
			fmt.Printf("err: %s\n", result.err)
		}
	}
}

