// Vending machine state machine with Result type

// State: Idle | HasCredit(cents) | Dispensing(change)
// Event: Insert(cents) | Select(code) | DispenseDone
// Result: Ok(newState) | Err(reason)

function step(state, event) {
  // Pattern match on (state, event)
  if (state.type === 'Idle') {
    if (event.type === 'Insert') {
      return { ok: true, value: { type: 'HasCredit', cents: event.cents } };
    } else if (event.type === 'Select') {
      return { ok: false, error: 'no_credit' };
    } else if (event.type === 'DispenseDone') {
      return { ok: false, error: 'not_dispensing' };
    }
  } else if (state.type === 'HasCredit') {
    if (event.type === 'Insert') {
      return { ok: true, value: { type: 'HasCredit', cents: state.cents + event.cents } };
    } else if (event.type === 'Select') {
      const prices = { 1: 125, 2: 75, 3: 100 };
      if (!(event.code in prices)) {
        return { ok: false, error: 'unknown_item' };
      }
      if (state.cents < prices[event.code]) {
        return { ok: false, error: 'insufficient_funds' };
      }
      return { ok: true, value: { type: 'Dispensing', change: state.cents - prices[event.code] } };
    } else if (event.type === 'DispenseDone') {
      return { ok: false, error: 'not_dispensing' };
    }
  } else if (state.type === 'Dispensing') {
    if (event.type === 'Insert') {
      return { ok: false, error: 'busy' };
    } else if (event.type === 'Select') {
      return { ok: false, error: 'busy' };
    } else if (event.type === 'DispenseDone') {
      return { ok: true, value: { type: 'Idle' } };
    }
  }
}

function formatOutput(result) {
  if (result.ok) {
    const state = result.value;
    if (state.type === 'Idle') {
      return 'ok: IDLE';
    } else if (state.type === 'HasCredit') {
      return `ok: CREDIT(${state.cents})`;
