from dataclasses import dataclass
from typing import Union

# State types
@dataclass
class Idle:
    pass

@dataclass
class HasCredit:
    cents: int

@dataclass
class Dispensing:
    change: int

State = Union[Idle, HasCredit, Dispensing]

# Event types
@dataclass
class Insert:
    cents: int

@dataclass
class Select:
    code: int

@dataclass
class DispenseDone:
    pass

Event = Union[Insert, Select, DispenseDone]

# Result type
@dataclass
class Ok:
    state: State

@dataclass
class Err:
    reason: str

Result = Union[Ok, Err]


def get_price(code: int) -> int | None:
    prices = {1: 125, 2: 75, 3: 100}
    return prices.get(code)


def step(state: State, event: Event) -> Result:
    match (state, event):
        # Idle transitions
        case (Idle(), Insert(cents)):
            return Ok(HasCredit(cents))
        case (Idle(), Select(_)):
            return Err("no_credit")
        case (Idle(), DispenseDone()):
            return Err("not_dispensing")

        # HasCredit transitions
        case (HasCredit(c), Insert(cents)):
            return Ok(HasCredit(c + cents))
        case (HasCredit(c), Select(code)):
            price = get_price(code)
            if price is None:
                return Err("unknown_item")
            elif c < price:
                return Err("insufficient_funds")
            else:
                return Ok(Dispensing(c - price))
        case (HasCredit(_), DispenseDone()):
            return Err("not_dispensing")

        # Dispensing transitions
        case (Dispensing(_), Insert(_)):
            return Err("busy")
        case (Dispensing(_), Select(_)):
            return Err("busy")
        case (Dispensing(ch), DispenseDone()):
            return Ok(Idle())


def format_state(state: State) -> str:
    match state:
        case Idle():
            return "IDLE"
        case HasCredit(cents):
            return f"CREDIT({cents})"
        case Dispensing(change):
            return f"DISPENSING({change})"


def print_result(result: Result) -> None:
    match result:
        case Ok(state):
            print(f"ok: {format_state(state)}")
        case Err(reason):
            print(f"err: {reason}")


def main() -> None:
    state: State = Idle()

    events: list[Event] = [
        Insert(50),
        Select(1),
        Insert(100),
        Select(1),
        Insert(50),
        DispenseDone(),
        Select(2),
        Insert(100),
        Select(2),
        DispenseDone(),
    ]

    for event in events:
        result = step(state, event)
        print_result(result)
        # Thread the state forward
        match result:
            case Ok(new_state):
                state = new_state
            case Err(_):
                # Keep previous state
                pass


if __name__ == "__main__":
    main()

