pure func diff(expr: Expr, var: string) -> Expr {
  match expr {
    Const(_) => Const(0),
    Var(name) => if name == var then Const(1) else Const(0),
    Add(a, b) => Add(diff(a, var), diff(b, var)),
    Mul(a, b) => Add(Mul(a, diff(b, var)), Mul(b, diff(a, var)))
  }
}

pure func simplify(expr: Expr) -> Expr {
  match expr {
    Const(n) => Const(n),
    Var(name) => Var(name),
    Add(a, b) => {
      let sa = simplify(a);
      let sb = simplify(b);
      match sa {
        Const(0) => sb,
        _ => match sb {
          Const(0) => sa,
          _ => Add(sa, sb)
        }
      }
    },
    Mul(a, b) => {
      let sa = simplify(a);
      let sb = simplify(b);
      match sa {
        Const(0) => Const(0),
        Const(1) => sb,
        _ => match sb {
          Const(0) => Const(0),
          Const(1) => sa,
          _ => Mul(sa, sb)
        }
      }
    }
  }
}

