  }

pure func treeDepth(tree: Tree) -> int =
  match tree {
    Leaf(_) => 1,
    Node(left, _, right) => {
      let leftDepth = treeDepth(left);
      let rightDepth = treeDepth(right);
      if leftDepth > rightDepth then leftDepth + 1 else rightDepth + 1
