package main

import (
	"fmt"
)

// Tree type - interface for union-like behavior
type Tree interface {
	isTree()
}

// Leaf variant - contains a single integer value
type Leaf struct {
	value int
}

func (Leaf) isTree() {}

// Node variant - contains left subtree, value, and right subtree
type Node struct {
	left  Tree
	value int
	right Tree
}

func (Node) isTree() {}

// mapTree recursively applies a function to all values in the tree
func mapTree(fn func(int) int, tree Tree) Tree {
	switch t := tree.(type) {
	case Leaf:
		return Leaf{value: fn(t.value)}
	case Node:
		return Node{
			left:  mapTree(fn, t.left),
			value: fn(t.value),
			right: mapTree(fn, t.right),
		}
	}
	return nil
}

// foldTree performs an in-order fold over tree values
func foldTree(fn func(int, int) int, acc int, tree Tree) int {
	switch t := tree.(type) {
	case Leaf:
		return fn(acc, t.value)
	case Node:
		// In-order: process left subtree, then node value, then right subtree
		acc = foldTree(fn, acc, t.left)
		acc = fn(acc, t.value)
		acc = foldTree(fn, acc, t.right)
		return acc
	}
	return acc
}

// treeToList performs in-order traversal returning list of integers
func treeToList(tree Tree) []int {
	var result []int
	var traverse func(Tree)
	traverse = func(t Tree) {
		switch n := t.(type) {
		case Leaf:
			result = append(result, n.value)
		case Node:
			traverse(n.left)
			result = append(result, n.value)
			traverse(n.right)
		}
	}
	traverse(tree)
	return result
}

// treeDepth returns the maximum depth of the tree (Leaf has depth 1)
func treeDepth(tree Tree) int {
	switch t := tree.(type) {
	case Leaf:
		return 1
	case Node:
		leftDepth := treeDepth(t.left)
		rightDepth := treeDepth(t.right)
		if leftDepth > rightDepth {
			return leftDepth + 1
		}
		return rightDepth + 1
	}
	return 0
}

func main() {
	// Build the tree:
	//        4
	//       / \
	//      2   6
	//     / \ / \
	//    1  3 5  7
	tree := Node{
		left: Node{
			left:  Leaf{value: 1},
			value: 2,
			right: Leaf{value: 3},
		},
		value: 4,
		right: Node{
			left:  Leaf{value: 5},
			value: 6,
			right: Leaf{value: 7},
		},
	}

	// Helper function to print list
	printList := func(list []int) {
		fmt.Print("[")
		for i, v := range list {
			if i > 0 {
				fmt.Print(", ")
			}
			fmt.Print(v)
		}
		fmt.Println("]")
	}

	// Test cases
	// treeToList(tree): [1, 2, 3, 4, 5, 6, 7]
	printList(treeToList(tree))

	// treeToList(mapTree(double, tree)): [2, 4, 6, 8, 10, 12, 14]
	double := func(x int) int { return x * 2 }
	printList(treeToList(mapTree(double, tree)))

	// foldTree(add, 0, tree): 28
	add := func(a, b int) int { return a + b }
	fmt.Println(foldTree(add, 0, tree))

	// treeDepth(tree): 3
	fmt.Println(treeDepth(tree))
}

