const mapTree = (fn, tree) => {
  if (tree.type === 'Leaf') {
    return Leaf(fn(tree.value));
  } else {
    return Node(
      mapTree(fn, tree.left),
      fn(tree.value),
      mapTree(fn, tree.right)
    );
  }
};

// foldTree(fn, acc, tree) - in-order fold over tree values
const foldTree = (fn, acc, tree) => {
  if (tree.type === 'Leaf') {
    return fn(acc, tree.value);
  } else {
    const leftResult = foldTree(fn, acc, tree.left);
    const middleResult = fn(leftResult, tree.value);
    const rightResult = foldTree(fn, middleResult, tree.right);
    return rightResult;
  }
};

