from typing import Union, Callable, List

# Define the Tree type with two variants: Leaf and Node
class Leaf:
    def __init__(self, value: int):
        self.value = value

class Node:
    def __init__(self, left: Union['Node', Leaf], value: int, right: Union['Node', Leaf]):
        self.left = left
        self.value = value
        self.right = right

Tree = Union[Leaf, Node]

def mapTree(fn: Callable[[int], int], tree: Tree) -> Tree:
    """Recursively apply function to all values in tree"""
    if isinstance(tree, Leaf):
        return Leaf(fn(tree.value))
    else:  # Node
        return Node(mapTree(fn, tree.left), fn(tree.value), mapTree(fn, tree.right))

def foldTree(fn: Callable[[int, int], int], acc: int, tree: Tree) -> int:
    """In-order fold over tree values"""
    if isinstance(tree, Leaf):
        return fn(acc, tree.value)
    else:  # Node
        left_result = foldTree(fn, acc, tree.left)
        node_result = fn(left_result, tree.value)
        right_result = foldTree(fn, node_result, tree.right)
        return right_result

def treeToList(tree: Tree) -> List[int]:
    """In-order traversal returning list of integers"""
    result = []

    def inorder(node: Tree):
        if isinstance(node, Leaf):
            result.append(node.value)
        else:  # Node
            inorder(node.left)
            result.append(node.value)
            inorder(node.right)

    inorder(tree)
    return result

def treeDepth(tree: Tree) -> int:
    """Return maximum depth of tree (Leaf has depth 1)"""
    if isinstance(tree, Leaf):
        return 1
    else:  # Node
        return 1 + max(treeDepth(tree.left), treeDepth(tree.right))

# Helper functions for testing
def double(x: int) -> int:
    return x * 2

def add(a: int, b: int) -> int:
