import std/io (println)

type Type = TVar(string) | TInt | TBool | TFunc(Type, Type)

type UResult = USuccess([(string, Type)]) | UFail

func showType(t: Type) -> string =
  match t {
    TVar(n) => "TVar(${n})",
    TInt => "TInt",
    TBool => "TBool",
    TFunc(a, r) => "TFunc(${showType(a)}, ${showType(r)})"
  }

func applyOne(name: string, replacement: Type, t: Type) -> Type =
  match t {
    TVar(n) => if n == name then replacement else TVar(n),
    TInt => TInt,
    TBool => TBool,
    TFunc(a, r) => TFunc(applyOne(name, replacement, a), applyOne(name, replacement, r))
  }

func apply(subst: [(string, Type)], t: Type) -> Type =
  match subst {
    [] => t,
    pair :: rest => match pair {
      (name, repl) => apply(rest, applyOne(name, repl, t))
    }
  }

func unify(t1: Type, t2: Type) -> UResult =
  match t1 {
    TInt => match t2 {
      TInt => USuccess([]),
      TVar(b) => USuccess([(b, TInt)]),
      _ => UFail
    },
    TBool => match t2 {
      TBool => USuccess([]),
      TVar(b) => USuccess([(b, TBool)]),
      _ => UFail
    },
    TVar(a) => USuccess([(a, t2)]),
    TFunc(a1, r1) => match t2 {
      TVar(b) => USuccess([(b, t1)]),
      TFunc(a2, r2) => match unify(a1, a2) {
        UFail => UFail,
        USuccess(s1) => match unify(apply(s1, r1), apply(s1, r2)) {
          UFail => UFail,
          USuccess(s2) => USuccess(concatSubst(s1, s2))
        }
      },
      _ => UFail
    }
  }

func concatSubst(s1: [(string, Type)], s2: [(string, Type)]) -> [(string, Type)] =
  match s1 {
    [] => s2,
    x :: rest => x :: concatSubst(rest, s2)
  }

func lookupVar(name: string, subst: [(string, Type)]) -> Type =
  match subst {
    [] => TVar(name),
    pair :: rest => match pair {
      (n, t) => if n == name then apply(rest, t) else lookupVar(name, rest)
    }
  }

export func main() -> () ! {IO} {
  let t1 = TFunc(TVar("a"), TInt);
  let t2 = TFunc(TBool, TVar("b"));
  match unify(t1, t2) {
    UFail => println("unification failed"),
    USuccess(s) => {
      let aType = lookupVar("a", s);
      let bType = lookupVar("b", s);
      println("a = ${showType(aType)}");
      println("b = ${showType(bType)}")
    }
  }
}

