from dataclasses import dataclass
from typing import List, Tuple


@dataclass
class Type:
    pass


@dataclass
class TVar(Type):
    name: str


@dataclass
class TInt(Type):
    pass


@dataclass
class TBool(Type):
    pass


@dataclass
class TFunc(Type):
    arg: Type
    result: Type


Substitution = List[Tuple[str, Type]]


def apply(subst: Substitution, t: Type) -> Type:
    if isinstance(t, TVar):
        for var_name, var_type in subst:
            if var_name == t.name:
                return apply(subst, var_type)
        return t
    elif isinstance(t, TInt) or isinstance(t, TBool):
        return t
    elif isinstance(t, TFunc):
        return TFunc(apply(subst, t.arg), apply(subst, t.result))
    else:
        return t


def unify(t1: Type, t2: Type) -> Substitution:
    if isinstance(t1, TInt) and isinstance(t2, TInt):
        return []
    elif isinstance(t1, TBool) and isinstance(t2, TBool):
        return []
    elif isinstance(t1, TVar):
        return [(t1.name, t2)]
    elif isinstance(t2, TVar):
        return [(t2.name, t1)]
    elif isinstance(t1, TFunc) and isinstance(t2, TFunc):
        subst1 = unify(t1.arg, t2.arg)
        subst2 = unify(apply(subst1, t1.result), apply(subst1, t2.result))
        return subst1 + subst2
    else:
        raise ValueError(f"Cannot unify {t1} with {t2}")


def main():
    t1 = TFunc(TVar("a"), TInt())
    t2 = TFunc(TBool(), TVar("b"))

    subst = unify(t1, t2)

    for var_name, var_type in subst:
        if isinstance(var_type, TBool):
            print(f"{var_name} = TBool")
        elif isinstance(var_type, TInt):
            print(f"{var_name} = TInt")


if __name__ == "__main__":
    main()
